OPJ_BOOL opj_j2k_write_cbd( opj_j2k_t *p_j2k,
                                                struct opj_stream_private *p_stream,
                                                struct opj_event_mgr * p_manager )
{
        OPJ_UINT32 i;
        OPJ_UINT32 l_cbd_size;
        OPJ_BYTE * l_current_data = 00;
        opj_image_t *l_image = 00;
        opj_image_comp_t * l_comp = 00;

        /* preconditions */
        assert(p_j2k != 00);
        assert(p_manager != 00);
        assert(p_stream != 00);

        l_image = p_j2k->m_private_image;
        l_cbd_size = 6 + p_j2k->m_private_image->numcomps;

        if (l_cbd_size > p_j2k->m_specific_param.m_encoder.m_header_tile_data_size) {
                OPJ_BYTE *new_header_tile_data = (OPJ_BYTE *) opj_realloc(p_j2k->m_specific_param.m_encoder.m_header_tile_data, l_cbd_size);
                if (! new_header_tile_data) {
                        opj_free(p_j2k->m_specific_param.m_encoder.m_header_tile_data);
                        p_j2k->m_specific_param.m_encoder.m_header_tile_data = NULL;
                        p_j2k->m_specific_param.m_encoder.m_header_tile_data_size = 0;
                        opj_event_msg(p_manager, EVT_ERROR, "Not enough memory to write CBD marker\n");
                        return OPJ_FALSE;
                }
                p_j2k->m_specific_param.m_encoder.m_header_tile_data = new_header_tile_data;
                p_j2k->m_specific_param.m_encoder.m_header_tile_data_size = l_cbd_size;
        }

        l_current_data = p_j2k->m_specific_param.m_encoder.m_header_tile_data;

        opj_write_bytes(l_current_data,J2K_MS_CBD,2);                   /* CBD */
        l_current_data += 2;

        opj_write_bytes(l_current_data,l_cbd_size-2,2);                 /* L_CBD */
        l_current_data += 2;

        opj_write_bytes(l_current_data,l_image->numcomps, 2);           /* Ncbd */
        l_current_data+=2;

        l_comp = l_image->comps;

        for (i=0;i<l_image->numcomps;++i) {
                opj_write_bytes(l_current_data, (l_comp->sgnd << 7) | (l_comp->prec - 1), 1);           /* Component bit depth */
                ++l_current_data;

                ++l_comp;
        }

        if (opj_stream_write_data(p_stream,p_j2k->m_specific_param.m_encoder.m_header_tile_data,l_cbd_size,p_manager) != l_cbd_size) {
                return OPJ_FALSE;
        }

        return OPJ_TRUE;
}

push_read_cb (GObject *source, GAsyncResult *res, gpointer user_data)
{
  PushHandle *handle = user_data;
  GError *error = NULL;
  gssize n;

  n = g_input_stream_read_finish (handle->in, res, &error);

  /* Ignore this read if we've subsequently been restarted. */
  if (handle->read_status != PUSH_READ_STATUS_NONE)
    {
      g_free (handle->buf);
      handle->buf = NULL;

      /* Queue another read if we've been subsequently restarted and
       * push_write_next_chunk () was called in the meantime. */
      if (handle->read_status == PUSH_READ_STATUS_DEFERRED)
        push_write_next_chunk (handle->msg, handle);

      return;
    }

  if (n > 0)
    {
      soup_message_body_append_take (handle->msg->request_body, handle->buf, n);
      handle->buf = NULL;
      handle->n_read += n;
      soup_session_unpause_message (G_VFS_BACKEND_HTTP (handle->backend)->session,
                                    handle->msg);
    }
  else if (n == 0)
    {
      g_free (handle->buf);
      handle->buf = NULL;

      if (handle->n_read != handle->size)
        {
          g_vfs_job_failed_literal (handle->job,
                                    G_IO_ERROR,
                                    G_IO_ERROR_FAILED,
                                    _("File length changed during transfer"));

          soup_session_cancel_message (G_VFS_BACKEND_HTTP (handle->backend)->session,
                                       handle->msg,
                                       SOUP_STATUS_CANCELLED);
        }
    }
  else
    {
      g_free (handle->buf);
      handle->buf = NULL;
      g_vfs_job_failed_from_error (handle->job, error);
      g_error_free (error);
      soup_session_cancel_message (G_VFS_BACKEND_HTTP (handle->backend)->session,
                                   handle->msg,
                                   SOUP_STATUS_CANCELLED);
    }
}

int ssl_renegotiate( ssl_context *ssl )
{
    int ret = POLARSSL_ERR_SSL_FEATURE_UNAVAILABLE;

#if defined(POLARSSL_SSL_SRV_C)
    /* On server, just send the request */
    if( ssl->endpoint == SSL_IS_SERVER )
    {
        if( ssl->state != SSL_HANDSHAKE_OVER )
            return( POLARSSL_ERR_SSL_BAD_INPUT_DATA );

        ssl->renegotiation = SSL_RENEGOTIATION_PENDING;

        /* Did we already try/start sending HelloRequest? */
        if( ssl->out_left != 0 )
            return( ssl_flush_output( ssl ) );

        return( ssl_write_hello_request( ssl ) );
    }
#endif /* POLARSSL_SSL_SRV_C */

#if defined(POLARSSL_SSL_CLI_C)
    /*
     * On client, either start the renegotiation process or,
     * if already in progress, continue the handshake
     */
    if( ssl->renegotiation != SSL_RENEGOTIATION )
    {
        if( ssl->state != SSL_HANDSHAKE_OVER )
            return( POLARSSL_ERR_SSL_BAD_INPUT_DATA );

        if( ( ret = ssl_start_renegotiation( ssl ) ) != 0 )
        {
            SSL_DEBUG_RET( 1, "ssl_start_renegotiation", ret );
            return( ret );
        }
    }
    else
    {
        if( ( ret = ssl_handshake( ssl ) ) != 0 )
        {
            SSL_DEBUG_RET( 1, "ssl_handshake", ret );
            return( ret );
        }
    }
#endif /* POLARSSL_SSL_CLI_C */

    return( ret );
}

static uint64_t vmxnet3_get_mac_low(MACAddr *addr)
