	res = uriDissectQueryMallocA(&queryList, &itemCount, pair, pair + strlen(pair));
	ASSERT_TRUE(res == URI_SUCCESS);
	ASSERT_TRUE(queryList != NULL);
	ASSERT_TRUE(itemCount == 1);
	ASSERT_TRUE(!strcmp(queryList->key, unescapedKey));
