qb_ipc_us_recv(struct qb_ipc_one_way * one_way,
	       void *msg, size_t len, int32_t timeout)
{
	int32_t result;
	int32_t final_rc = 0;
	int32_t processed = 0;
	int32_t to_recv = len;
	char *data = msg;

	qb_sigpipe_ctl(QB_SIGPIPE_IGNORE);

retry_recv:
	result = recv(one_way->u.us.sock, &data[processed], to_recv,
		      MSG_NOSIGNAL | MSG_WAITALL);

	if (result == -1) {
		if (errno == EAGAIN && (processed > 0 || timeout == -1)) {
			result = qb_ipc_us_ready(one_way, NULL, timeout, POLLIN);
			if (result == 0 || result == -EAGAIN) {
				goto retry_recv;
			}
			final_rc = result;
			goto cleanup_sigpipe;
		} else if (errno == ECONNRESET || errno == EPIPE) {
			final_rc = -ENOTCONN;
			goto cleanup_sigpipe;
		} else {
			final_rc = -errno;
			goto cleanup_sigpipe;
		}
	}

	if (result == 0) {
		final_rc = -ENOTCONN;
		goto cleanup_sigpipe;
	}
	processed += result;
	to_recv -= result;
	if (processed != len) {
		goto retry_recv;
	}
	final_rc = processed;

cleanup_sigpipe:
	qb_sigpipe_ctl(QB_SIGPIPE_DEFAULT);
	return final_rc;
}

qb_ipcs_run(struct qb_ipcs_service *s)
{
	int32_t res = 0;

	if (s->poll_fns.dispatch_add == NULL ||
	    s->poll_fns.dispatch_mod == NULL ||
	    s->poll_fns.dispatch_del == NULL) {

		res = -EINVAL;
		goto run_cleanup;
	}

	switch (s->type) {
	case QB_IPC_SOCKET:
		qb_ipcs_us_init((struct qb_ipcs_service *)s);
		break;
	case QB_IPC_SHM:
#ifdef DISABLE_IPC_SHM
		res = -ENOTSUP;
#else
		qb_ipcs_shm_init((struct qb_ipcs_service *)s);
#endif /* DISABLE_IPC_SHM */
		break;
	case QB_IPC_POSIX_MQ:
	case QB_IPC_SYSV_MQ:
		res = -ENOTSUP;
		break;
	default:
		res = -EINVAL;
		break;
	}

	if (res == 0) {
		res = qb_ipcs_us_publish(s);
		if (res < 0) {
			(void)qb_ipcs_us_withdraw(s);
			goto run_cleanup;
		}
	}

run_cleanup:
	if (res < 0) {
		/* Failed to run services, removing initial alloc reference. */
		qb_ipcs_unref(s);
	}

	return res;
}

process_auth(int32_t fd, int32_t revents, void *d)
{
	struct ipc_auth_data *data = (struct ipc_auth_data *) d;

	int32_t res = 0;
#ifdef SO_PASSCRED
	int off = 0;
#endif

	if (data->s->server_sock == -1) {
		qb_util_log(LOG_DEBUG, "Closing fd (%d) for server shutdown", fd);
		res = -ESHUTDOWN;
		goto cleanup_and_return;
	}

	if (revents & POLLNVAL) {
		qb_util_log(LOG_DEBUG, "NVAL conn fd (%d)", fd);
		res = -EINVAL;
		goto cleanup_and_return;
	}
	if (revents & POLLHUP) {
		qb_util_log(LOG_DEBUG, "HUP conn fd (%d)", fd);
		res = -ESHUTDOWN;
		goto cleanup_and_return;
	}
	if ((revents & POLLIN) == 0) {
		return 0;
	}

	res = qb_ipc_us_recv_msghdr(data);
	if (res == -EAGAIN) {
		/* yield to mainloop, Let mainloop call us again */
		return 0;
	}

	if (res != data->len) {
		res = -EIO;
		goto cleanup_and_return;
	}

	res = qb_ipc_auth_creds(data);

cleanup_and_return:
#ifdef SO_PASSCRED
	setsockopt(data->sock, SOL_SOCKET, SO_PASSCRED, &off, sizeof(off));
#endif

	(void)data->s->poll_fns.dispatch_del(data->sock);

	if (res < 0) {
		close(data->sock);
	} else if (data->msg.req.hdr.id == QB_IPC_MSG_AUTHENTICATE) {
		(void)handle_new_connection(data->s, res, data->sock, &data->msg, data->len, &data->ugp);
	} else {
		close(data->sock);
	}
	destroy_ipc_auth_data(data);

	return 1;
}

qb_rb_close(struct qb_ringbuffer_s * rb)
{
	if (rb == NULL) {
		return;
	}
	qb_enter();

	(void)qb_atomic_int_dec_and_test(&rb->shared_hdr->ref_count);
	(void)qb_rb_close_helper(rb, rb->flags & QB_RB_FLAG_CREATE, QB_FALSE);
}

qb_ipcs_stats_get(struct qb_ipcs_service * s,
		  struct qb_ipcs_stats * stats, int32_t clear_after_read)
{
	if (s == NULL) {
		return -EINVAL;
	}
	memcpy(stats, &s->stats, sizeof(struct qb_ipcs_stats));
	if (clear_after_read) {
		memset(&s->stats, 0, sizeof(struct qb_ipcs_stats));
	}
	return 0;
}

create_proxy_socket (char *template)
{
  g_autofree char *user_runtime_dir = flatpak_get_real_xdg_runtime_dir ();
  g_autofree char *proxy_socket_dir = g_build_filename (user_runtime_dir, ".dbus-proxy", NULL);
  g_autofree char *proxy_socket = g_build_filename (proxy_socket_dir, template, NULL);
  int fd;

  if (!glnx_shutil_mkdir_p_at (AT_FDCWD, proxy_socket_dir, 0755, NULL, NULL))
    return NULL;

  fd = g_mkstemp (proxy_socket);
  if (fd == -1)
    return NULL;

  close (fd);

  return g_steal_pointer (&proxy_socket);
}

static void binder_thread_dec_tmpref(struct binder_thread *thread)
{
	/*
	 * atomic is used to protect the counter value while
	 * it cannot reach zero or thread->is_dead is false
	 */
	binder_inner_proc_lock(thread->proc);
	atomic_dec(&thread->tmp_ref);
	if (thread->is_dead && !atomic_read(&thread->tmp_ref)) {
		binder_inner_proc_unlock(thread->proc);
		binder_free_thread(thread);
		return;
	}
	binder_inner_proc_unlock(thread->proc);
}

static void binder_dec_node_tmpref(struct binder_node *node)
{
	bool free_node;

	binder_node_inner_lock(node);
	if (!node->proc)
		spin_lock(&binder_dead_nodes_lock);
	node->tmp_refs--;
	BUG_ON(node->tmp_refs < 0);
	if (!node->proc)
		spin_unlock(&binder_dead_nodes_lock);
	/*
	 * Call binder_dec_node() to check if all refcounts are 0
	 * and cleanup is needed. Calling with strong=0 and internal=1
	 * causes no actual reference to be released in binder_dec_node().
	 * If that changes, a change is needed here too.
	 */
	free_node = binder_dec_node_nilocked(node, 0, 1);
	binder_node_inner_unlock(node);
	if (free_node)
		binder_free_node(node);
}

void CWebServer::Cmd_UpdateDevice(WebEmSession & session, const request& req, Json::Value &root)
{
	if (session.rights < 1)
	{
		session.reply_status = reply::forbidden;
		return; //only user or higher allowed
	}

	std::string idx = request::findValue(&req, "idx");

	if (!IsIdxForUser(&session, atoi(idx.c_str())))
	{
		_log.Log(LOG_ERROR, "User: %s tried to update an Unauthorized device!", session.username.c_str());
		session.reply_status = reply::forbidden;
		return;
	}

	std::string hid = request::findValue(&req, "hid");
	std::string did = request::findValue(&req, "did");
	std::string dunit = request::findValue(&req, "dunit");
	std::string dtype = request::findValue(&req, "dtype");
	std::string dsubtype = request::findValue(&req, "dsubtype");

	std::string nvalue = request::findValue(&req, "nvalue");
	std::string svalue = request::findValue(&req, "svalue");

	if ((nvalue.empty() && svalue.empty()))
	{
		return;
	}

	int signallevel = 12;
	int batterylevel = 255;

	if (idx.empty())
	{
		//No index supplied, check if raw parameters where supplied
		if (
			(hid.empty()) ||
			(did.empty()) ||
			(dunit.empty()) ||
			(dtype.empty()) ||
			(dsubtype.empty())
			)
			return;
	}
	else
	{
		//Get the raw device parameters
		std::vector<std::vector<std::string> > result;
		result = m_sql.safe_query("SELECT HardwareID, DeviceID, Unit, Type, SubType FROM DeviceStatus WHERE (ID=='%q')",
			idx.c_str());
		if (result.empty())
			return;
		hid = result[0][0];
		did = result[0][1];
		dunit = result[0][2];
		dtype = result[0][3];
		dsubtype = result[0][4];
	}

	int HardwareID = atoi(hid.c_str());
	std::string DeviceID = did;
	int unit = atoi(dunit.c_str());
	int devType = atoi(dtype.c_str());
	int subType = atoi(dsubtype.c_str());

	uint64_t ulIdx = std::strtoull(idx.c_str(), nullptr, 10);

	int invalue = atoi(nvalue.c_str());

	std::string sSignalLevel = request::findValue(&req, "rssi");
	if (sSignalLevel != "")
	{
		signallevel = atoi(sSignalLevel.c_str());
	}
	std::string sBatteryLevel = request::findValue(&req, "battery");
	if (sBatteryLevel != "")
	{
		batterylevel = atoi(sBatteryLevel.c_str());
	}
	if (m_mainworker.UpdateDevice(HardwareID, DeviceID, unit, devType, subType, invalue, svalue, signallevel, batterylevel))
	{
		root["status"] = "OK";
		root["title"] = "Update Device";
	}
}

void CWebServer::Cmd_SetSetpoint(WebEmSession & session, const request& req, Json::Value &root)
{
	bool bHaveUser = (session.username != "");
	int iUser = -1;
	int urights = 3;
	if (bHaveUser)
	{
		iUser = FindUser(session.username.c_str());
		if (iUser != -1)
		{
			urights = static_cast<int>(m_users[iUser].userrights);
		}
	}
	if (urights < 1)
		return;

	std::string idx = request::findValue(&req, "idx");
	std::string setpoint = request::findValue(&req, "setpoint");
	if (
		(idx.empty()) ||
		(setpoint.empty())
