vips_foreign_load_gif_scan_application_ext( VipsForeignLoadGif *gif,
	GifByteType *extension )
{
	gboolean have_netscape;

	/* The 11-byte NETSCAPE extension.
	 */
	have_netscape = FALSE;
	if( extension[0] == 11 &&
		vips_isprefix( "NETSCAPE2.0", (const char*) (extension + 1) ) ) 
		have_netscape = TRUE;

	while( extension != NULL ) {
		if( vips_foreign_load_gif_ext_next( gif, &extension ) )
			return( -1 ); 

		if( have_netscape &&
			extension &&
			extension[0] == 3 &&
			extension[1] == 1 ) 
			gif->loop = extension[2] | (extension[3] << 8);
	}

	return( 0 );
}

static TCGv gen_lea_modrm_1(AddressParts a)
{
    TCGv ea;

    TCGV_UNUSED(ea);
    if (a.index >= 0) {
        if (a.scale == 0) {
            ea = cpu_regs[a.index];
        } else {
            tcg_gen_shli_tl(cpu_A0, cpu_regs[a.index], a.scale);
            ea = cpu_A0;
        }
        if (a.base >= 0) {
            tcg_gen_add_tl(cpu_A0, ea, cpu_regs[a.base]);
            ea = cpu_A0;
        }
    } else if (a.base >= 0) {
        ea = cpu_regs[a.base];
    }
    if (TCGV_IS_UNUSED(ea)) {
        tcg_gen_movi_tl(cpu_A0, a.disp);
        ea = cpu_A0;
    } else if (a.disp != 0) {
        tcg_gen_addi_tl(cpu_A0, ea, a.disp);
        ea = cpu_A0;
    }

    return ea;
}

else if (type == NBD_REPLY_TYPE_OFFSET_DATA) {
  /* The spec states that 0-length requests are unspecified, but
   * 0-length replies are broken. Still, it's easy enough to support
   * them as an extension, so we use < instead of <=.
   */
  if (cmd->type != NBD_CMD_READ) {
    SET_NEXT_STATE (%.DEAD);
    set_error (0, "invalid command for receiving offset-data chunk, "
               "cmd->type=%" PRIu16 ", "
               "this is likely to be a bug in the server",
               cmd->type);
    return 0;
  }
  if (length < sizeof h->sbuf.sr.payload.offset_data) {
    SET_NEXT_STATE (%.DEAD);
    set_error (0, "too short length in NBD_REPLY_TYPE_OFFSET_DATA");
    return 0;
  }
  h->rbuf = &h->sbuf.sr.payload.offset_data;
  h->rlen = sizeof h->sbuf.sr.payload.offset_data;
  SET_NEXT_STATE (%RECV_OFFSET_DATA);
  return 0;
}

