  // being destroyed.
  Emit("will-destroy");
  ResetManagedWebContents(async);
}

v8::Local<v8::Value> WebContents::GetWebPreferences(
    v8::Isolate* isolate) const {
  auto* web_preferences = WebContentsPreferences::From(web_contents());
